export const bundledAssets = {"/index.html":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#172a3a\">\n  <meta name=\"description\" content=\"Consultas, entregas y ventas en un solo lugar.\">\n  <title>Mi mesa de ventas</title>\n  <link rel=\"manifest\" href=\"/manifest.webmanifest\">\n  <link rel=\"stylesheet\" href=\"/style.css\">\n  <script src=\"/app.js\" defer></script>\n</head>\n<body>\n  <div class=\"shell\">\n    <header class=\"topbar\">\n      <div><span class=\"eyebrow\">MARKETPLACE · WHATSAPP</span><h1>Mi mesa de ventas</h1></div>\n      <div class=\"top-actions\"><span id=\"today\"></span><button id=\"refresh\" class=\"icon-button\" title=\"Actualizar datos\">↻</button><button id=\"logout\" class=\"secondary\" title=\"Cerrar sesión\">Salir</button></div>\n    </header>\n    <nav class=\"tabs\" aria-label=\"Secciones\">\n      <button class=\"tab active\" data-view=\"inicio\">Inicio</button>\n      <button class=\"tab\" data-view=\"consultas\">Consultas</button>\n      <button class=\"tab\" data-view=\"productos\">Productos</button>\n      <button class=\"tab\" data-view=\"asistente\">Asistente</button>\n    </nav>\n    <main>\n      <div id=\"notice\" class=\"notice\" role=\"status\" hidden></div>\n      <div id=\"loading\" class=\"notice\" role=\"status\">Cargando productos y consultas…</div>\n      <section id=\"inicio\" class=\"view active\">\n        <div class=\"hero\"><div><span class=\"eyebrow\">TU DÍA, CLARO</span><h2>Responde, confirma y entrega.</h2><p>Registra solo las consultas que necesitan seguimiento. Cada venta se cuenta cuando marcas la entrega.</p></div><button class=\"primary\" data-action=\"new-lead\">+ Nueva consulta</button></div>\n        <div class=\"metrics\" id=\"metrics\"></div>\n        <div class=\"grid-two\"><div class=\"panel\"><div class=\"section-head\"><h3>Próximas entregas</h3><span class=\"muted\">Pedidos agendados</span></div><div id=\"upcoming\" class=\"list\"></div></div><div class=\"panel\"><div class=\"section-head\"><h3>Qué necesita acción</h3></div><div id=\"todo\" class=\"list\"></div></div></div>\n      </section>\n      <section id=\"consultas\" class=\"view\">\n        <div class=\"section-head\"><div><span class=\"eyebrow\">CLIENTES Y PEDIDOS</span><h2>Consultas</h2></div><div class=\"actions\"><button class=\"secondary\" id=\"export\">Exportar CSV</button><button class=\"primary\" data-action=\"new-lead\">+ Registrar</button></div></div>\n        <div class=\"toolbar\"><input id=\"search\" type=\"search\" placeholder=\"Buscar por alias o producto\"><select id=\"status-filter\"><option value=\"\">Todos los estados</option><option>consulta</option><option>interesado</option><option>confirmado</option><option>comprado</option><option>agendado</option><option>entregado</option><option>cancelado</option></select></div>\n        <div id=\"lead-list\" class=\"cards\"></div>\n      </section>\n      <section id=\"productos\" class=\"view\">\n        <div class=\"section-head\"><div><span class=\"eyebrow\">PRECIOS Y DISPONIBILIDAD</span><h2>Productos</h2></div><button class=\"primary\" data-action=\"new-product\">+ Agregar</button></div>\n        <p class=\"hint\">El precio mínimo es interno: el asistente lo usa para sugerir una negociación, pero no se lo muestra al cliente. Actualiza disponibilidad antes de confirmar una entrega.</p>\n        <div id=\"product-list\" class=\"cards product-grid\"></div>\n      </section>\n      <section id=\"asistente\" class=\"view\">\n        <div class=\"section-head\"><div><span class=\"eyebrow\">RESPUESTAS CON TU CRITERIO</span><h2>Asistente de ventas</h2></div></div>\n        <div class=\"grid-two assistant-layout\"><div class=\"panel\"><label>Producto<select id=\"ai-product\"></select></label><label>Qué quieres responder<select id=\"ai-goal\"><option value=\"responder consulta\">Consulta general</option><option value=\"pregunta por disponibilidad\">Disponibilidad</option><option value=\"negociar precio\">Pide rebaja</option><option value=\"coordinar entrega\">Coordinar entrega</option><option value=\"cotizar envío por Yango\">Envío por Yango</option></select></label><label>Mensaje del cliente<textarea id=\"customer-message\" rows=\"6\" placeholder=\"Pega aquí lo que te escribió. Evita incluir su número, dirección exacta o datos bancarios.\"></textarea></label><div class=\"actions\"><button id=\"base-draft\" class=\"secondary\">Respuesta base</button><button id=\"ai-draft\" class=\"primary\">Sugerir con Gemini</button></div><p class=\"hint\">Gemini recibe el mensaje y los datos del producto. Revisa el texto antes de enviarlo. Nunca confirma por sí solo stock, pago ni fecha.</p></div><div class=\"panel output-panel\"><div class=\"section-head\"><h3>Texto para revisar</h3><button id=\"copy-draft\" class=\"secondary\" disabled>Copiar</button></div><div id=\"draft\" class=\"draft-placeholder\">Aquí aparecerá tu respuesta. Pégala en Messenger o WhatsApp después de revisarla.</div><div id=\"draft-check\" class=\"checkline\" hidden>Antes de enviar: revisa precio, disponibilidad y fecha.</div></div></div>\n      </section>\n    </main>\n    <footer>Privado · tus chats siguen en Messenger y WhatsApp · los mensajes se envían solo cuando tú los copias</footer>\n  </div>\n\n  <dialog id=\"lead-dialog\"><form id=\"lead-form\" method=\"dialog\"><div class=\"dialog-head\"><div><span class=\"eyebrow\">SEGUIMIENTO</span><h2 id=\"lead-dialog-title\">Nueva consulta</h2></div><button type=\"button\" class=\"icon-button\" data-close=\"lead-dialog\">×</button></div><input type=\"hidden\" name=\"id\"><div class=\"form-grid\"><label>Nombre o alias<input name=\"alias\" required maxlength=\"100\" placeholder=\"Ej.: Cliente PB6010\"></label><label>Canal<select name=\"channel\"><option>Marketplace</option><option>WhatsApp</option><option>Otro</option></select></label><label>Producto<select name=\"product_id\" required></select></label><label>Estado<select name=\"status\"><option>consulta</option><option>interesado</option><option>confirmado</option><option>comprado</option><option>agendado</option><option>entregado</option><option>cancelado</option></select></label><label>Precio acordado (Bs)<input name=\"amount\" type=\"number\" min=\"0\" step=\"1\" required></label><label>Costo real (Bs)<input name=\"actual_cost\" type=\"number\" min=\"0\" step=\"1\" required></label><label>Otros gastos (Bs)<input name=\"expenses\" type=\"number\" min=\"0\" step=\"1\" value=\"0\" required></label><label>Modalidad<select name=\"delivery_mode\"><option value=\"por_definir\">Por definir</option><option value=\"persona\">En persona</option><option value=\"yango\">Yango</option></select></label><label>Lugar / barrio<input name=\"delivery_place\" maxlength=\"200\" placeholder=\"UAGRM, Cine Center o barrio\"></label><label>Fecha y hora de entrega<input name=\"delivery_at\" type=\"datetime-local\"></label></div><label class=\"checkbox\"><input name=\"paid\" type=\"checkbox\"> Pago del producto verificado</label><label>Nota breve<textarea name=\"notes\" rows=\"3\" maxlength=\"1000\" placeholder=\"Qué falta confirmar\"></textarea></label><p id=\"lead-form-error\" class=\"form-error\" role=\"alert\" hidden></p><div class=\"dialog-actions\"><button type=\"button\" class=\"secondary\" data-close=\"lead-dialog\">Cancelar</button><button id=\"save-lead\" type=\"submit\" class=\"primary\">Guardar</button></div></form></dialog>\n\n  <dialog id=\"product-dialog\"><form id=\"product-form\" method=\"dialog\"><div class=\"dialog-head\"><div><span class=\"eyebrow\">FICHA INTERNA</span><h2 id=\"product-dialog-title\">Nuevo producto</h2></div><button type=\"button\" class=\"icon-button\" data-close=\"product-dialog\">×</button></div><input type=\"hidden\" name=\"id\"><label>Nombre<input name=\"name\" required maxlength=\"100\"></label><label>Datos comprobados<textarea name=\"facts\" rows=\"4\" maxlength=\"1200\" placeholder=\"Solo lo que puedas afirmar al cliente\"></textarea></label><div class=\"form-grid\"><label>Costo (Bs)<input name=\"cost\" type=\"number\" min=\"0\" step=\"1\" required></label><label>Precio publicado (Bs)<input name=\"price\" type=\"number\" min=\"0\" step=\"1\" required></label><label>Precio mínimo interno (Bs)<input name=\"min_price\" type=\"number\" min=\"0\" step=\"1\" required></label><label>Disponibilidad<select name=\"availability\"><option value=\"por_confirmar\">Por confirmar</option><option value=\"proveedor_confirmado\">Proveedor confirmó</option><option value=\"en_mano\">En mano</option></select></label><label>Unidades en mano<input name=\"available_units\" type=\"number\" min=\"0\" step=\"1\" value=\"0\" required></label><label>Fecha posible de entrega<input name=\"ready_date\" type=\"date\"></label></div><label class=\"checkbox\"><input name=\"availability_checked\" type=\"checkbox\"> Verifiqué esta disponibilidad ahora</label><p class=\"hint\">Marca esto solo después de comprobarlo. La respuesta al cliente seguirá pidiendo confirmación antes de cerrar.</p><p id=\"product-form-error\" class=\"form-error\" role=\"alert\" hidden></p><div class=\"dialog-actions\"><button type=\"button\" class=\"secondary\" data-close=\"product-dialog\">Cancelar</button><button id=\"save-product\" type=\"submit\" class=\"primary\">Guardar</button></div></form></dialog>\n</body>\n</html>\n"},"/login.html":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"es\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#172a3a\">\n  <meta name=\"robots\" content=\"noindex,nofollow\">\n  <title>Entrar · Mi mesa de ventas</title>\n  <link rel=\"stylesheet\" href=\"/style.css\">\n  <script src=\"/login.js\" defer></script>\n</head>\n<body class=\"login-body\">\n  <main class=\"login-card\">\n    <div class=\"login-mark\" aria-hidden=\"true\">↗</div>\n    <span class=\"eyebrow\">TU ESPACIO PRIVADO</span>\n    <h1>Mi mesa de ventas</h1>\n    <p>Entra para revisar consultas, entregas, productos y respuestas.</p>\n    <form id=\"login-form\">\n      <label for=\"username\">Usuario</label>\n      <input id=\"username\" name=\"username\" type=\"text\" autocomplete=\"username\" value=\"propietario\" readonly>\n      <label for=\"password\">Contraseña</label>\n      <input id=\"password\" name=\"password\" type=\"password\" autocomplete=\"current-password\" required autofocus>\n      <button id=\"login-button\" class=\"primary\" type=\"submit\">Entrar</button>\n    </form>\n    <p id=\"login-error\" class=\"login-error\" role=\"alert\" hidden></p>\n    <p class=\"login-help\">Guarda la contraseña en el gestor del celular y la PC. Después podrás entrar con autocompletado o huella, sin escribirla cada vez. La sesión dura 7 días.</p>\n    <details class=\"recovery\"><summary>¿Perdiste el acceso?</summary><p>Si aún controlas tu cuenta de Cloudflare, cambia el secreto <code>APP_PASSWORD</code> del Worker por una contraseña nueva y guárdala en tu gestor. El cambio cerrará las sesiones anteriores. No envíes esa contraseña por chat.</p></details>\n  </main>\n</body>\n</html>\n"},"/style.css":{"type":"text/css; charset=utf-8","body":":root{font-family:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;color:#172a3a;background:#f3f4ef;font-synthesis:none}*{box-sizing:border-box}body{margin:0}button,input,select,textarea{font:inherit}button{cursor:pointer}button:disabled{opacity:.55;cursor:wait}.shell{max-width:1160px;margin:auto;padding:0 20px}.topbar{display:flex;justify-content:space-between;align-items:center;padding:30px 0 20px}.topbar h1{font-size:24px;letter-spacing:-.03em;margin:3px 0}.eyebrow{font-size:11px;font-weight:800;letter-spacing:.15em;color:#d46e3d}.top-actions{display:flex;align-items:center;gap:12px;color:#65717a;font-size:13px}.icon-button{border:1px solid #d7ddd9;background:white;color:#172a3a;border-radius:12px;min-width:38px;height:38px;font-size:21px}.tabs{display:flex;gap:8px;border-bottom:1px solid #dce1dc;overflow:auto}.tab{border:0;background:none;color:#65717a;padding:12px 18px;font-weight:700;white-space:nowrap;border-bottom:3px solid transparent}.tab.active{color:#122c37;border-color:#e77a47}main{padding:28px 0 50px}.view{display:none}.view.active{display:block}h2{font-size:29px;letter-spacing:-.04em;margin:4px 0 10px}h3{font-size:18px;letter-spacing:-.02em;margin:0}p{line-height:1.5}.hero{background:#172a3a;color:white;border-radius:24px;padding:30px;display:flex;justify-content:space-between;align-items:end;gap:20px}.hero h2{font-size:36px;max-width:520px}.hero p{color:#c5d1d4;max-width:580px;margin-bottom:0}.primary,.secondary{border:0;border-radius:12px;padding:11px 17px;font-weight:750;white-space:nowrap}.primary{background:#df7447;color:white}.primary:hover{background:#c76339}.secondary{background:#eef1ee;color:#172a3a;border:1px solid #dce2dd}.secondary:hover{background:#e3e9e3}.hero .primary{background:#ffac75;color:#172a3a}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:18px 0}.metric,.panel,.card{background:white;border:1px solid #e0e5df;border-radius:19px;box-shadow:0 5px 20px rgba(22,42,58,.035)}.metric{padding:20px}.metric strong{display:block;font-size:26px;letter-spacing:-.04em;margin-top:8px}.metric span,.muted{font-size:12px;color:#68787b}.grid-two{display:grid;grid-template-columns:1fr 1fr;gap:16px}.panel{padding:22px}.section-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:0 0 18px}.section-head h2{margin:2px 0}.actions{display:flex;gap:8px;align-items:center}.list{display:grid;gap:10px}.row{border:1px solid #e7eae7;border-radius:12px;padding:12px 14px;display:flex;justify-content:space-between;gap:10px;align-items:center}.row strong{display:block;font-size:14px}.row small{color:#6d7b7f}.empty{color:#66777c;background:#f8f9f5;padding:18px;border-radius:12px;font-size:14px}.toolbar{display:flex;gap:10px;margin:4px 0 16px}.toolbar input{flex:1}.toolbar select{min-width:180px}.cards{display:grid;gap:12px}.product-grid{grid-template-columns:repeat(3,1fr)}.card{padding:20px}.card-head{display:flex;justify-content:space-between;align-items:start;gap:15px}.card h3{margin-bottom:5px}.card p{font-size:14px;color:#53666c;margin:12px 0}.badge{display:inline-block;background:#edf4f0;color:#2c7569;font-size:11px;font-weight:800;padding:5px 9px;border-radius:50px;text-transform:capitalize}.badge.warn{background:#fff3e6;color:#a65c2b}.badge.done{background:#eef0f5;color:#65718a}.card-meta{display:flex;gap:15px;flex-wrap:wrap;font-size:13px;color:#617177;margin:14px 0}.card .secondary{padding:7px 12px;font-size:13px}.price{font-size:23px;font-weight:800;letter-spacing:-.03em}.hint{color:#607176;font-size:13px;max-width:780px}.assistant-layout{align-items:start}.assistant-layout label{margin-bottom:15px}.output-panel{min-height:370px}.draft-placeholder{background:#f7f8f4;border:1px dashed #cbd6cf;border-radius:14px;padding:20px;color:#697a7d;min-height:230px;white-space:pre-wrap;line-height:1.6}.draft-placeholder.ready{color:#182e39;border-style:solid;background:#fff}.checkline{font-size:12px;color:#9c652e;margin-top:12px}.notice{background:#fff0df;color:#74451e;border:1px solid #f6d8b5;padding:13px 15px;border-radius:12px;margin-bottom:15px}.notice.success{background:#e7f5ed;color:#2e6847;border-color:#c5e6d2}label{display:block;font-size:13px;font-weight:700;color:#42555a}input,select,textarea{width:100%;background:white;border:1px solid #ced8d2;border-radius:10px;padding:10px 12px;color:#172a3a;outline:none;margin-top:6px}input:focus,select:focus,textarea:focus{border-color:#df7447;box-shadow:0 0 0 3px #df744722}textarea{resize:vertical}dialog{border:0;border-radius:22px;padding:0;width:min(680px,calc(100vw - 26px));max-height:92vh;box-shadow:0 25px 80px #142a3d55}dialog::backdrop{background:#12232d99}dialog form{padding:25px;overflow:auto;max-height:92vh}.dialog-head{display:flex;align-items:start;justify-content:space-between}.dialog-head h2{font-size:25px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:14px 0}.dialog-actions{display:flex;justify-content:end;gap:8px;border-top:1px solid #e7eae6;padding-top:17px;margin-top:18px}.checkbox{display:flex;align-items:center;gap:8px;margin:14px 0}.checkbox input{width:auto;margin:0}.dialog-head+.form-grid{margin-top:15px}footer{border-top:1px solid #dde4dd;padding:20px 0 32px;color:#879292;font-size:11px;text-align:center}@media(max-width:750px){.shell{padding:0 13px}.topbar{padding:20px 0 14px}.topbar h1{font-size:21px}.top-actions #today{display:none}.tabs{gap:0}.tab{padding:11px 13px;font-size:13px}main{padding-top:18px}.hero{display:block;padding:22px}.hero h2{font-size:29px}.hero .primary{margin-top:15px}.metrics{grid-template-columns:repeat(2,1fr);gap:9px}.metric{padding:15px}.metric strong{font-size:22px}.grid-two,.product-grid{grid-template-columns:1fr}.panel{padding:17px}.section-head{align-items:start}.section-head .actions{flex-wrap:wrap;justify-content:end}.toolbar{display:block}.toolbar select{margin-top:8px}.form-grid{grid-template-columns:1fr 1fr;gap:10px}dialog form{padding:18px}}@media(max-width:420px){.form-grid{grid-template-columns:1fr}.actions{flex-wrap:wrap}.section-head h2{font-size:25px}}\n.login-body{min-height:100vh;min-height:100dvh;display:grid;place-items:center;padding:22px;background:radial-gradient(circle at 15% 10%,#e6f0e9 0,transparent 34%),radial-gradient(circle at 85% 85%,#fce8d8 0,transparent 32%),#f3f4ef}.login-card{width:min(100%,430px);padding:36px;border:1px solid #dce4dc;border-radius:24px;background:#fff;box-shadow:0 20px 70px #172a3a14}.login-mark{display:grid;place-items:center;width:48px;height:48px;border-radius:15px;background:#172a3a;color:#ffb887;font-size:28px;font-weight:800;margin-bottom:28px}.login-card h1{font-size:31px;letter-spacing:-.045em;margin:8px 0}.login-card p{color:#63747a;margin:0 0 25px}.login-card form{display:grid;gap:13px}.login-card input{margin-top:0}.login-card button{width:100%;margin-top:5px}.login-card .login-error{background:#fff0df;color:#74451e;border:1px solid #f6d8b5;border-radius:10px;padding:11px;margin:18px 0 0;font-size:13px}.login-card small{display:block;color:#7e8d8d;margin-top:28px;text-align:center}.login-card [hidden]{display:none}@media(max-width:480px){.login-card{padding:27px}.login-card h1{font-size:27px}}\n.login-card .login-help{font-size:13px;line-height:1.5;margin:20px 0 0}.recovery{margin-top:20px;font-size:13px;color:#526970}.recovery summary{cursor:pointer;font-weight:700}.recovery p{margin:10px 0 0}.login-card input[readonly]{background:#f5f6f3;color:#617177}\n.form-error{color:#8f351f;background:#fff0e9;border:1px solid #f2c9b8;border-radius:10px;padding:10px 12px;font-size:13px}.form-error[hidden],#loading[hidden]{display:none}\n@media(max-width:750px){.icon-button{min-width:44px;height:44px}.tab{min-height:44px}.primary,.secondary{min-height:44px}}\n"},"/app.js":{"type":"text/javascript; charset=utf-8","body":"const $ = selector => document.querySelector(selector);\nconst state = { products: [], leads: [], aiReady: false, view: 'inicio', pendingLeadId: null };\nconst labels = { consulta: 'Consulta', interesado: 'Interesado', confirmado: 'Confirmado', comprado: 'Comprado', agendado: 'Agendado', entregado: 'Entregado', cancelado: 'Cancelado' };\nconst availability = { por_confirmar: 'Por confirmar', proveedor_confirmado: 'Proveedor confirmó', en_mano: 'En mano' };\nconst money = value => `Bs ${Number(value || 0).toLocaleString('es-BO')}`;\nconst localDate = value => value ? new Intl.DateTimeFormat('es-BO', { dateStyle: 'medium', timeStyle: value.length > 10 ? 'short' : undefined }).format(new Date(value.length > 10 ? value : `${value}T12:00:00`)) : 'Sin fecha';\nfunction element(tag, text, className = '') { const node = document.createElement(tag); node.textContent = text; if (className) node.className = className; return node; }\nfunction notice(message, success = false) { const box = $('#notice'); box.textContent = message; box.className = success ? 'notice success' : 'notice'; box.hidden = false; clearTimeout(notice.timer); notice.timer = setTimeout(() => box.hidden = true, 6500); }\nasync function api(path, method = 'GET', data) {\n  const response = await fetch(path, { method, headers: data ? { 'Content-Type': 'application/json' } : undefined, body: data ? JSON.stringify(data) : undefined, credentials: 'same-origin' });\n  const result = await response.json().catch(() => ({}));\n  if (response.status === 401) { location.replace('/login'); throw new Error('La sesión terminó.'); }\n  if (!response.ok) throw new Error(result.error || `Error ${response.status}`);\n  return result;\n}\nasync function refresh() {\n  $('#loading').hidden = false;\n  try { const data = await api('/api/state'); state.products = data.products; state.leads = data.leads; state.aiReady = data.ai_ready; render(); }\n  catch (e) { notice(`No se pudo cargar: ${e.message}`); }\n  finally { $('#loading').hidden = true; }\n}\nfunction switchView(view) {\n  state.view = view;\n  document.querySelectorAll('.view').forEach(node => node.classList.toggle('active', node.id === view));\n  document.querySelectorAll('.tab').forEach(node => node.classList.toggle('active', node.dataset.view === view));\n  window.scrollTo({ top: 0, behavior: 'smooth' });\n}\nfunction render() { renderHome(); renderLeads(); renderProducts(); renderPickers(); }\nfunction renderHome() {\n  const metrics = $('#metrics'); metrics.replaceChildren();\n  const open = state.leads.filter(l => !['entregado', 'cancelado'].includes(l.status));\n  const confirmed = state.leads.filter(l => ['confirmado', 'comprado', 'agendado'].includes(l.status));\n  const delivered = state.leads.filter(l => l.status === 'entregado');\n  const margin = delivered.filter(l => l.paid).reduce((sum, l) => sum + l.amount - l.actual_cost - l.expenses, 0);\n  [['Consultas activas', open.length], ['Pedidos confirmados', confirmed.length], ['Entregados', delivered.length], ['Margen cobrado¹', money(margin)]].forEach(([label, value]) => { const card = element('div', '', 'metric'); card.append(element('span', label), element('strong', String(value))); metrics.append(card); });\n  const upcoming = $('#upcoming'); upcoming.replaceChildren();\n  const scheduled = state.leads.filter(l => l.delivery_at && !['entregado', 'cancelado'].includes(l.status)).sort((a, b) => a.delivery_at.localeCompare(b.delivery_at)).slice(0, 5);\n  if (!scheduled.length) upcoming.append(element('div', 'Aún no hay entregas agendadas.', 'empty'));\n  scheduled.forEach(l => upcoming.append(row(l.alias, `${l.product_name} · ${localDate(l.delivery_at)} · ${l.delivery_place || 'lugar pendiente'}`)));\n  const todo = $('#todo'); todo.replaceChildren();\n  const unconfirmed = state.leads.filter(l => ['consulta', 'interesado'].includes(l.status)).slice(0, 4);\n  const missingDate = state.leads.filter(l => ['confirmado', 'comprado'].includes(l.status) && !l.delivery_at).slice(0, 3);\n  if (!unconfirmed.length && !missingDate.length) todo.append(element('div', 'Todo al día. Revisa la disponibilidad antes de cerrar un pedido.', 'empty'));\n  unconfirmed.forEach(l => todo.append(row(l.alias, `${l.product_name} · responder o confirmar`)));\n  missingDate.forEach(l => todo.append(row(l.alias, `${l.product_name} · falta fecha de entrega`)));\n  const foot = element('small', '¹ Precio cobrado menos costo y gastos anotados; no incluye gastos que aún no registres.', 'muted'); todo.append(foot);\n}\nfunction row(title, subtitle) { const div = element('div', '', 'row'); const inner = element('div', ''); inner.append(element('strong', title), element('small', subtitle)); div.append(inner); return div; }\nfunction renderLeads() {\n  const list = $('#lead-list'); list.replaceChildren();\n  const query = $('#search').value.trim().toLowerCase(), filter = $('#status-filter').value;\n  const leads = state.leads.filter(l => (!filter || l.status === filter) && (!query || `${l.alias} ${l.product_name}`.toLowerCase().includes(query)));\n  if (!leads.length) { list.append(element('div', 'No hay consultas con ese filtro.', 'empty')); return; }\n  leads.forEach(l => {\n    const card = element('article', '', 'card'); const head = element('div', '', 'card-head'); const info = element('div', '');\n    info.append(element('h3', l.alias), element('span', `${l.product_name} · ${l.channel}`, 'muted'));\n    head.append(info, element('span', labels[l.status], `badge ${l.status === 'entregado' ? 'done' : ['consulta', 'interesado'].includes(l.status) ? 'warn' : ''}`));\n    const meta = element('div', '', 'card-meta');\n    meta.append(element('span', `Venta ${money(l.amount)}`), element('span', `Margen estimado ${money(l.amount - l.actual_cost - l.expenses)}`), element('span', l.delivery_at ? `Entrega ${localDate(l.delivery_at)}` : 'Entrega sin agendar'), element('span', l.paid ? 'Pago verificado' : 'Pago pendiente'));\n    const button = element('button', 'Abrir / actualizar', 'secondary'); button.addEventListener('click', () => openLead(l));\n    card.append(head, meta, button); list.append(card);\n  });\n}\nfunction renderProducts() {\n  const list = $('#product-list'); list.replaceChildren();\n  state.products.forEach(p => {\n    const card = element('article', '', 'card'); const head = element('div', '', 'card-head'); const info = element('div', '');\n    info.append(element('h3', p.name), element('span', availability[p.availability], `badge ${p.availability === 'por_confirmar' ? 'warn' : ''}`)); head.append(info, element('div', money(p.price), 'price'));\n    const facts = element('p', p.facts || 'Sin datos de producto');\n    const meta = element('div', '', 'card-meta'); meta.append(element('span', `Costo ${money(p.cost)}`), element('span', `Mínimo interno ${money(p.min_price)}`), element('span', `En mano: ${p.available_units}`), element('span', `Entrega: ${localDate(p.ready_date)}`), element('span', p.availability_checked_at ? `Verificado: ${localDate(p.availability_checked_at.replace(' ', 'T'))}` : 'Disponibilidad sin verificar'));\n    const button = element('button', 'Editar ficha', 'secondary'); button.addEventListener('click', () => openProduct(p)); card.append(head, facts, meta, button); list.append(card);\n  });\n}\nfunction renderPickers() {\n  const pickers = [$('#ai-product'), $('#lead-form [name=\"product_id\"]')];\n  pickers.forEach(picker => { const selected = picker.value; picker.replaceChildren(); state.products.forEach(p => { const option = element('option', p.name); option.value = p.id; picker.append(option); }); if (state.products.some(p => p.id === selected)) picker.value = selected; });\n  $('#ai-draft').disabled = !state.aiReady;\n  $('#ai-draft').title = state.aiReady ? '' : 'Configura la clave de Gemini para activar esta opción';\n}\nfunction openLead(lead) {\n  const form = $('#lead-form'); form.reset(); state.pendingLeadId = lead ? null : crypto.randomUUID();\n  $('#lead-form-error').hidden = true;\n  $('#lead-dialog-title').textContent = lead ? 'Actualizar consulta' : 'Nueva consulta';\n  form.elements.id.value = lead?.id || '';\n  if (lead) {\n    for (const key of ['alias','channel','product_id','status','amount','actual_cost','expenses','delivery_mode','delivery_place','delivery_at','notes']) form.elements[key].value = lead[key] ?? '';\n    form.elements.paid.checked = !!lead.paid;\n    form.elements.channel.disabled = true; form.elements.product_id.disabled = true;\n  } else {\n    form.elements.channel.disabled = false; form.elements.product_id.disabled = false;\n    form.elements.status.value = 'consulta'; form.elements.delivery_mode.value = 'por_definir'; form.elements.expenses.value = '0';\n    const product = state.products.find(p => p.id === form.elements.product_id.value);\n    form.elements.amount.value = product?.price || 0; form.elements.actual_cost.value = product?.cost || 0;\n  }\n  $('#lead-dialog').showModal();\n}\nfunction openProduct(product) {\n  const form = $('#product-form'); form.reset(); $('#product-dialog-title').textContent = product ? 'Editar producto' : 'Nuevo producto';\n  $('#product-form-error').hidden = true;\n  form.elements.id.value = product?.id || '';\n  if (product) for (const key of ['name','facts','cost','price','min_price','availability','available_units','ready_date']) form.elements[key].value = product[key] ?? '';\n  else { form.elements.availability.value = 'por_confirmar'; form.elements.available_units.value = 0; }\n  $('#product-dialog').showModal();\n}\nasync function saveLead(event) {\n  event.preventDefault(); const form = event.currentTarget, button = $('#save-lead'); if (button.disabled) return;\n  const data = Object.fromEntries(new FormData(form)); data.paid = form.elements.paid.checked;\n  $('#lead-form-error').hidden = true;\n  button.disabled = true; button.textContent = 'Guardando…';\n  try {\n    if (data.id) await api(`/api/leads/${encodeURIComponent(data.id)}`, 'PATCH', data);\n    else await api('/api/leads', 'POST', { ...data, request_id: state.pendingLeadId });\n    state.pendingLeadId = null; $('#lead-dialog').close(); await refresh(); notice('Consulta guardada.', true);\n  } catch (e) { const box = $('#lead-form-error'); box.textContent = `No se guardó: ${e.message}`; box.hidden = false; }\n  finally { button.disabled = false; button.textContent = 'Guardar'; }\n}\nasync function saveProduct(event) {\n  event.preventDefault(); const form = event.currentTarget, button = $('#save-product'); if (button.disabled) return;\n  const data = Object.fromEntries(new FormData(form)); data.availability_checked = form.elements.availability_checked.checked; $('#product-form-error').hidden = true; button.disabled = true; button.textContent = 'Guardando…';\n  try { await api(data.id ? `/api/products/${encodeURIComponent(data.id)}` : '/api/products', data.id ? 'PATCH' : 'POST', data); $('#product-dialog').close(); await refresh(); notice('Producto guardado.', true); }\n  catch (e) { const box = $('#product-form-error'); box.textContent = `No se guardó: ${e.message}`; box.hidden = false; }\n  finally { button.disabled = false; button.textContent = 'Guardar'; }\n}\nfunction baseDraft() {\n  const product = state.products.find(p => p.id === $('#ai-product').value); if (!product) return;\n  const goal = $('#ai-goal').value;\n  const firstFact = product.facts.split(/\\.\\s/)[0].replace(/\\.$/, '');\n  let text = `¡Hola! ${product.name} está a ${money(product.price)}.${firstFact ? ` ${firstFact}.` : ''}`;\n  text += ' Te confirmo disponibilidad y fecha de entrega antes de cerrar el pedido.';\n  if (goal.includes('rebaja')) text += ` El precio publicado es ${money(product.price)}. Si me dices qué modalidad de entrega te conviene, reviso qué puedo ofrecerte.`;\n  else if (goal.includes('Yango')) text += ' ¿En qué barrio o referencia estás? Te cotizo Yango sin compromiso. El producto se paga antes de despacharlo y el envío se cotiza aparte.';\n  else if (goal.includes('entrega')) text += ' Podemos coordinar en la UAGRM (módulos), Cine Center u otro punto público. En persona pagas al recibir. ¿Qué día y punto te convienen?';\n  else text += ' ¿Prefieres entrega en persona o envío por Yango?';\n  setDraft(text);\n}\nfunction setDraft(text) { const box = $('#draft'); box.textContent = text; box.classList.add('ready'); $('#copy-draft').disabled = false; $('#draft-check').hidden = false; }\nasync function aiDraft() {\n  const button = $('#ai-draft'); if (button.disabled) return;\n  const message = $('#customer-message').value.trim(); if (!message) { notice('Pega primero el mensaje del cliente.'); return; }\n  baseDraft();\n  button.disabled = true; button.textContent = 'Preparando…';\n  try { const result = await api('/api/ai', 'POST', { product_id: $('#ai-product').value, goal: $('#ai-goal').value, customer_message: message }); setDraft(result.draft); }\n  catch (e) { notice(`${e.message} La respuesta base sigue disponible para revisar y copiar.`); }\n  finally { button.disabled = !state.aiReady; button.textContent = 'Sugerir con Gemini'; }\n}\nfunction exportCsv() {\n  const cols = ['alias','channel','product_name','status','amount','actual_cost','expenses','delivery_mode','delivery_place','delivery_at','paid','notes','created_at'];\n  const quote = value => `\"${String(value ?? '').replaceAll('\"', '\"\"')}\"`;\n  const csv = '\\ufeff' + [cols.join(','), ...state.leads.map(l => cols.map(key => quote(l[key])).join(','))].join('\\r\\n');\n  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));\n  const link = document.createElement('a'); link.href = url; link.download = `ventas-${new Date().toISOString().slice(0, 10)}.csv`; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);\n}\n\ndocument.querySelectorAll('.tab').forEach(button => button.addEventListener('click', () => switchView(button.dataset.view)));\ndocument.querySelectorAll('[data-action=\"new-lead\"]').forEach(button => button.addEventListener('click', () => openLead()));\ndocument.querySelector('[data-action=\"new-product\"]').addEventListener('click', () => openProduct());\ndocument.querySelectorAll('[data-close]').forEach(button => button.addEventListener('click', () => document.getElementById(button.dataset.close).close()));\n$('#lead-form').addEventListener('submit', saveLead); $('#product-form').addEventListener('submit', saveProduct);\n$('#lead-form [name=\"product_id\"]').addEventListener('change', event => { const p = state.products.find(p => p.id === event.target.value); if (p) { const form = $('#lead-form'); form.elements.amount.value = p.price; form.elements.actual_cost.value = p.cost; } });\n$('#search').addEventListener('input', renderLeads); $('#status-filter').addEventListener('change', renderLeads);\n$('#refresh').addEventListener('click', refresh); $('#export').addEventListener('click', exportCsv);\n$('#logout').addEventListener('click', async () => { try { await api('/api/logout', 'POST'); location.replace('/login'); } catch (e) { notice(e.message); } });\n$('#base-draft').addEventListener('click', baseDraft); $('#ai-draft').addEventListener('click', aiDraft);\n$('#copy-draft').addEventListener('click', async () => { try { await navigator.clipboard.writeText($('#draft').textContent); notice('Texto copiado. Revísalo antes de enviarlo.', true); } catch { notice('No se pudo copiar automáticamente. Selecciona el texto.'); } });\n$('#today').textContent = new Intl.DateTimeFormat('es-BO', { dateStyle: 'full', timeZone: 'America/La_Paz' }).format(new Date());\nrefresh();\n"},"/login.js":{"type":"text/javascript; charset=utf-8","body":"const form = document.getElementById('login-form');\nconst button = document.getElementById('login-button');\nconst message = document.getElementById('login-error');\nfunction showError(text) { message.textContent = text; message.hidden = false; }\n\nfetch('/api/session', { credentials: 'same-origin', cache: 'no-store' })\n  .then(response => response.json())\n  .then(session => {\n    if (session.authenticated) location.replace('/');\n    else if (!session.configured) { showError('El acceso aún no está configurado. Añade APP_PASSWORD como secreto del Worker en Cloudflare y guárdalo en tu gestor de contraseñas.'); button.disabled = true; }\n  })\n  .catch(() => showError('No se pudo comprobar el estado del sistema. Recarga la página.'));\n\nform.addEventListener('submit', async event => {\n  event.preventDefault();\n  if (button.disabled) return;\n  message.hidden = true;\n  button.disabled = true;\n  button.textContent = 'Entrando…';\n  try {\n    const response = await fetch('/api/login', {\n      method: 'POST', credentials: 'same-origin', cache: 'no-store',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ password: form.elements.password.value })\n    });\n    const result = await response.json().catch(() => ({}));\n    if (!response.ok) throw new Error(result.error || `Error ${response.status}`);\n    form.elements.password.value = '';\n    location.replace('/');\n  } catch (error) {\n    showError(error.message);\n    button.disabled = false;\n    button.textContent = 'Entrar';\n  }\n});\n"},"/manifest.webmanifest":{"type":"application/manifest+json; charset=utf-8","body":"{\"name\":\"Mi mesa de ventas\",\"short_name\":\"Mis ventas\",\"start_url\":\"/\",\"display\":\"standalone\",\"background_color\":\"#f3f4ef\",\"theme_color\":\"#172a3a\"}\n"}};
